export default function makeController() {
  let initialized = false;
  let kT = 21.0;
  let tNorm = 0.45;
  let vxEst = 0, vyEst = 0, vzEst = 0;
  let dxEst = 0, dyEst = 0, dzEst = 0;
  let rollBias = 0, pitchBias = 0;
  let rollRef = 0, pitchRef = 0;
  let yawInt = 0;
  let gateIdx = 0;
  let phase = 'align';
  let settle = 0;

  const GATES_X = [-1.15, 0.15, 1.35];
  const GATES_Y = [1.05, 1.40, 1.05];
  const GATES_Z = [-0.85, 0.25, 1.05];

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vxEst = v.x; vyEst = v.y; vzEst = v.z;
      } else {
        const evx = v.x - vxEst;
        const evy = v.y - vyEst;
        const evz = v.z - vzEst;
        vxEst += 0.50 * evx;
        vyEst += 0.48 * evy;
        vzEst += 0.50 * evz;

        if (p.y > 0.10) {
          dxEst = clamp(dxEst + 6.5 * evx, -8.5, 8.5);
          dyEst = clamp(dyEst + 4.0 * evy, -6.5, 6.5);
          dzEst = clamp(dzEst + 6.5 * evz, -8.5, 8.5);
        }
      }

      if (p.y > 0.10) {
        rollBias = clamp(rollBias + 0.9 * (rollRef - att.roll) * dt, -0.25, 0.25);
        pitchBias = clamp(pitchBias + 0.9 * (pitchRef - att.pitch) * dt, -0.25, 0.25);
      }

      if (obs.gateIndex !== gateIdx) {
        gateIdx = obs.gateIndex;
        phase = 'clear_prev';
        settle = 0;
      }

      let tx, ty, tz, vxFf = 0, vyFf = 0, vzFf = 0;
      let kpX = 6.0, kdX = 4.4;
      let kpY = 7.5, kdY = 4.8;
      let kpZ = 6.5, kdZ = 4.5;
      let maxPosErrX = 0.60;

      // 1. After crossing a gate, clear the gate plane by 12 cm before turning laterally
      if (phase === 'clear_prev' && gateIdx > 0) {
        const prev = gateIdx - 1;
        if (p.x < GATES_X[prev] + 0.12) {
          tx = GATES_X[prev] + 0.18;
          ty = GATES_Y[prev];
          tz = GATES_Z[prev];
          vxFf = 0.45;
          kpX = 7.5; kdX = 5.0;
          kpY = 9.5; kdY = 5.5;
          kpZ = 10.5; kdZ = 5.8;
        } else {
          phase = 'align';
          settle = 0;
        }
      }

      if (phase !== 'clear_prev') {
        if (obs.gateIndex < 3) {
          const g = obs.nextGate.centre;
          const errY = Math.abs(g.y - p.y);
          const errZ = Math.abs(g.z - p.z);

          if (phase !== 'cross' && p.x > g.x - 0.14) {
            phase = 'recover';
          }

          if (phase === 'recover') {
            tx = g.x - 0.50;
            if (p.x > g.x - 0.18 && (errY > 0.17 || errZ > 0.085)) {
              ty = p.y;
              tz = p.z;
            } else {
              ty = g.y;
              tz = g.z;
            }
            maxPosErrX = 0.35;
            kpX = 8.5; kdX = 5.5;
            if (p.x < g.x - 0.32) {
              phase = 'align';
              settle = 0;
            }
          } else if (phase === 'align') {
            ty = g.y;
            tz = g.z;
            kpZ = 8.2; kdZ = 5.2;

            // While laterally unaligned in Z or Y, hold X well back from the gate plane so gusts cannot push into the frame
            if (errZ > 0.10 || errY > 0.17) {
              tx = obs.gateIndex === 0 ? g.x - 0.55 : g.x - 0.78;
              maxPosErrX = 0.22;
              if (p.x + vxEst * 0.35 > g.x - 0.42) {
                kpX = 9.0; kdX = 5.8;
                maxPosErrX = 0.45;
              }
            } else {
              tx = g.x - 0.38;
              maxPosErrX = 0.32;
            }

            const distYZ = Math.hypot(ty - p.y, tz - p.z);
            const velYZ = Math.hypot(vyEst, vzEst);
            if (Math.abs((g.x - 0.38) - p.x) < 0.16 && distYZ < 0.068 && velYZ < 0.24 && Math.abs(vxEst) < 0.30) {
              settle++;
            } else {
              settle = Math.max(0, settle - 1);
            }
            if (settle >= 5) {
              phase = 'cross';
            }
          }

          if (phase === 'cross') {
            const dxGate = g.x - p.x;
            const tCross = clamp(dxGate / Math.max(0.5, vxEst + 0.3), 0.02, 0.30);
            const yPred = p.y + vyEst * tCross;
            const zPred = p.z + vzEst * tCross;

            if (dxGate > 0.21 && (Math.abs(yPred - g.y) > 0.15 || Math.abs(zPred - g.z) > 0.080)) {
              phase = 'align';
              settle = 0;
              tx = g.x - 0.38;
              ty = g.y;
              tz = g.z;
            } else {
              tx = g.x + 0.34;
              ty = g.y;
              tz = g.z;
              vxFf = 1.05;
              kpX = 8.5; kdX = 5.0;
              kpY = 9.5; kdY = 5.5;
              kpZ = 11.5; kdZ = 6.2;
            }
          }
        } else {
          const pad = obs.pad.centre;
          tx = pad.x;
          tz = pad.z;
          const distXZ = Math.hypot(tx - p.x, tz - p.z);
          const speedXZ = Math.hypot(vxEst, vzEst);
          const urgent = obs.t > 21.0;

          if (phase !== 'descend') {
            ty = 0.38;
            maxPosErrX = 0.24;
            kpX = 7.2; kdX = 5.2;
            kpZ = 7.2; kdZ = 5.2;
            if ((distXZ < 0.12 && speedXZ < 0.24 && p.y < 0.54 && Math.abs(vyEst) < 0.24) || (urgent && distXZ < 0.14)) {
              phase = 'descend';
            }
          }

          if (phase === 'descend') {
            kpX = 8.0; kdX = 5.2;
            kpZ = 8.0; kdZ = 5.2;
            maxPosErrX = 0.24;
            if (!urgent && (distXZ > 0.125 || speedXZ > 0.28)) {
              ty = Math.max(0.16, p.y);
              vyFf = 0;
            } else {
              ty = Math.max(0.04, p.y - (urgent ? 0.12 : 0.09));
              const maxSink = p.y > 0.20 ? (urgent ? 0.45 : 0.34) : (urgent ? 0.22 : 0.15);
              vyFf = clamp((0.06 - p.y) * (urgent ? 2.0 : 1.5), -maxSink, 0.15);
            }
          }
        }
      }

      const cd = 0.58;
      const ex = clamp(tx - p.x, -maxPosErrX, maxPosErrX);
      const ez = clamp(tz - p.z, -0.45, 0.45);
      const ey = clamp(ty - p.y, -0.35, 0.45);

      let axDes = clamp(kpX * ex + kdX * (vxFf - vxEst) - dxEst + cd * vxEst, -4.8, 4.8);
      let azDes = clamp(kpZ * ez + kdZ * (vzFf - vzEst) - dzEst + cd * vzEst, -4.8, 4.8);
      const ayDes = clamp(kpY * ey + kdY * (vyFf - vyEst) - dyEst + cd * vyEst, -4.2, 6.0);

      // Strong wall-avoidance guard
      if (p.x + vxEst * 0.45 > 2.48) axDes = Math.min(axDes, -4.8);
      if (p.x + vxEst * 0.45 < -2.48) axDes = Math.max(axDes, 4.8);
      if (p.z + vzEst * 0.45 > 2.48) azDes = Math.min(azDes, -4.8);
      if (p.z + vzEst * 0.45 < -2.48) azDes = Math.max(azDes, 4.8);

      const onPad = obs.gateIndex === 3 &&
        Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.115 &&
        p.y <= 0.088 &&
        Math.hypot(v.x, v.y, v.z) < 0.32;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const gTotal = Math.max(4.5, 9.81 + ayDes);
      const aBodyX = cy * axDes - sy * azDes;
      const aBodyZ = sy * axDes + cy * azDes;

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.16) ? 0.14 : 0.48;
      const pitchTarget = onPad ? 0 : clamp(Math.atan2(aBodyX, gTotal), -maxTilt, maxTilt);
      const rollTarget = onPad ? 0 : clamp(Math.atan2(-aBodyZ, gTotal), -maxTilt, maxTilt);

      pitchRef += (pitchTarget - pitchRef) * 0.22;
      rollRef += (rollTarget - rollRef) * 0.22;

      const pitch = onPad ? 0 : clamp(pitchTarget + pitchBias, -maxTilt, maxTilt);
      const roll = onPad ? 0 : clamp(rollTarget + rollBias, -maxTilt, maxTilt);

      const dirY = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrust = onPad ? 0.02 : clamp((9.81 + ayDes) / (kT * dirY), 0.05, 1.0);

      yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.0 * att.yaw - 1.2 * yawInt - 0.2 * rates.yaw, -2, 2);

      tNorm += (thrust - tNorm) * 0.22;
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirZ = -sy * bodyX + cy * bodyZ;
      const aThrust = kT * tNorm;
      vxEst += (aThrust * dirX - cd * vxEst + dxEst) * dt;
      vyEst += (aThrust * dirY - 9.81 - cd * vyEst + dyEst) * dt;
      vzEst += (aThrust * dirZ - cd * vzEst + dzEst) * dt;

      return { thrust, roll, pitch, yawRate };
    },
  };
