export default function makeController() {
  let initialized = false;
  let kT = 21.0;
  let tNorm = 0.45;
  let vxEst = 0, vyEst = 0, vzEst = 0;
  let dxEst = 0, dyEst = 0, dzEst = 0;
  let rollBias = 0, pitchBias = 0;
  let rollRef = 0, pitchRef = 0;
  let yawInt = 0;
  let gateIdx = 0;
  let phase = 'align';
  let settle = 0;

  const GATES_X = [-1.15, 0.15, 1.35];
  const GATES_Y = [1.05, 1.40, 1.05];
  const GATES_Z = [-0.85, 0.25, 1.05];

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vxEst = v.x; vyEst = v.y; vzEst = v.z;
      } else {
        const evx = v.x - vxEst;
        const evy = v.y - vyEst;
        const evz = v.z - vzEst;
        vxEst += 0.52 * evx;
        vyEst += 0.48 * evy;
        vzEst += 0.52 * evz;

        if (p.y > 0.10) {
          dxEst = clamp(dxEst + 7.0 * evx, -9.5, 9.5);
          dyEst = clamp(dyEst + 4.2 * evy, -6.5, 6.5);
          dzEst = clamp(dzEst + 7.0 * evz, -9.5, 9.5);
        }
      }

      if (p.y > 0.10) {
        rollBias = clamp(rollBias + 0.9 * (rollRef - att.roll) * dt, -0.28, 0.28);
        pitchBias = clamp(pitchBias + 0.9 * (pitchRef - att.pitch) * dt, -0.28, 0.28);
      }

      if (obs.gateIndex !== gateIdx) {
        gateIdx = obs.gateIndex;
        phase = 'clear_prev';
        settle = 0;
      }

      let tx, ty, tz, vxFf = 0, vyFf = 0, vzFf = 0;
      let kpX = 6.2, kdX = 4.6;
      let kpY = 7.5, kdY = 4.8;
      let kpZ = 7.0, kdZ = 4.8;
      let maxPosErrX = 0.50;

      // 1. After crossing a gate, clear the gate plane by 12 cm before turning laterally
      if (phase === 'clear_prev' && gateIdx > 0) {
        const prev = gateIdx - 1;
        if (p.x < GATES_X[prev] + 0.12) {
          tx = GATES_X[prev] + 0.18;
          ty = GATES_Y[prev];
          tz = GATES_Z[prev];
          vxFf = 0.40;
          kpX = 7.5; kdX = 5.0;
          kpY = 9.5; kdY = 5.5;
          kpZ = 10.5; kdZ = 5.8;
        } else {
          phase = 'align';
          settle = 0;
        }
      }

      if (phase !== 'clear_prev') {
        if (obs.gateIndex < 3) {
          const g = obs.nextGate.centre;
          const errY = Math.abs(g.y - p.y);
          const errZ = Math.abs(g.z - p.z);

          if (phase !== 'cross' && p.x > g.x - 0.14) {
            phase = 'recover';
          }

          if (phase === 'recover') {
            tx = g.x - 0.52;
            if (p.x > g.x - 0.18 && (errY > 0.17 || errZ > 0.085)) {
              ty = p.y;
              tz = p.z;
            } else {
              ty = g.y;
              tz = g.z;
            }
            maxPosErrX = 0.40;
            kpX = 8.5; kdX = 5.5;
            if (p.x < g.x - 0.34) {
              phase = 'align';
              settle = 0;
            }
          } else if (phase === 'align') {
            ty = g.y;
            tz = g.z;
            kpZ = 8.5; kdZ = 5.4;

            if (errZ > 0.095 || errY > 0.16) {
              tx = obs.gateIndex === 0 ? g.x - 0.55 : g.x - 0.82;
              maxPosErrX = 0.22;
              if (p.x + vxEst * 0.40 > g.x - 0.45) {
                kpX = 9.5; kdX = 6.0;
                maxPosErrX = 0.50;
              }
            } else {
              tx = g.x - 0.38;
              maxPosErrX = 0.32;
            }

            const distYZ = Math.hypot(ty - p.y, tz - p.z);
            const velYZ = Math.hypot(vyEst, vzEst);
            if (Math.abs((g.x - 0.38) - p.x) < 0.16 && distYZ < 0.068 && velYZ < 0.24 && Math.abs(vxEst) < 0.30) {
              settle++;
            } else {
              settle = Math.max(0, settle - 1);
            }
            if (settle >= 5) {
              phase = 'cross';
            }
          }

          if (phase === 'cross') {
            const dxGate = g.x - p.x;
            const tCross = clamp(dxGate / Math.max(0.5, vxEst + 0.3), 0.02, 0.30);
            const yPred = p.y + vyEst * tCross;
            const zPred = p.z + vzEst * tCross;

            if (dxGate > 0.21 && (Math.abs(yPred - g.y) > 0.15 || Math.abs(zPred - g.z) > 0.080)) {
              phase = 'align';
              settle = 0;
              tx = g.x - 0.38;
              ty = g.y;
              tz = g.z;
            } else {
              tx = g.x + 0.34;
              ty = g.y;
              tz = g.z;
              vxFf = 1.05;
              kpX = 8.5; kdX = 5.0;
              kpY = 9.5; kdY = 5.5;
              kpZ = 11.5; kdZ = 6.2;
            }
          }
        } else {
          const pad = obs.pad.centre;
          tx = pad.x;
          tz = pad.z;
          const distXZ = Math.hypot(tx - p.x, tz - p.z);
