          const urgent = obs.t > 20.5;

          if (phase !== 'descend') {
            // Do not drop altitude rapidly while still braking from Gate 2 crossing
            ty = (distXZ > 0.35 || vxEst > 0.55) ? Math.max(0.65, p.y - 0.12) : 0.38;
            maxPosErrX = 0.24;
            kpX = 7.5; kdX = 5.2;
            kpZ = 7.5; kdZ = 5.2;
            if ((distXZ < 0.12 && speedXZ < 0.24 && p.y < 0.54 && Math.abs(vyEst) < 0.24) || (urgent && distXZ < 0.14)) {
              phase = 'descend';
            }
          }

          if (phase === 'descend') {
            kpX = 8.2; kdX = 5.2;
            kpZ = 8.2; kdZ = 5.2;
            maxPosErrX = 0.24;
            if (!urgent && (distXZ > 0.13 || speedXZ > 0.30)) {
              ty = Math.max(0.15, p.y);
              vyFf = 0;
            } else {
              ty = Math.max(0.04, p.y - (urgent ? 0.12 : 0.09));
              const maxSink = p.y > 0.18 ? (urgent ? 0.42 : 0.32) : (urgent ? 0.20 : 0.14);
              vyFf = clamp((0.06 - p.y) * (urgent ? 2.0 : 1.5), -maxSink, 0.15);
            }
          }
        }
      }

      const cd = 0.58;
      const ex = clamp(tx - p.x, -maxPosErrX, maxPosErrX);
      const ez = clamp(tz - p.z, -0.45, 0.45);
      // Limit negative ey so we never command near-zero collective thrust during descent
      const ey = clamp(ty - p.y, -0.18, 0.45);

      let axDes = clamp(kpX * ex + kdX * (vxFf - vxEst) - dxEst + cd * vxEst, -5.0, 5.0);
      let azDes = clamp(kpZ * ez + kdZ * (vzFf - vzEst) - dzEst + cd * vzEst, -5.0, 5.0);
      // Never command ayDes < -2.2 so motors maintain strong attitude/horizontal authority
      const ayDes = clamp(kpY * ey + kdY * (vyFf - vyEst) - dyEst + cd * vyEst, -2.2, 6.0);

      // Strong wall-avoidance guard
      if (p.x + vxEst * 0.45 > 2.45) axDes = Math.min(axDes, -5.0);
      if (p.x + vxEst * 0.45 < -2.45) axDes = Math.max(axDes, 5.0);
      if (p.z + vzEst * 0.45 > 2.45) azDes = Math.min(azDes, -5.0);
      if (p.z + vzEst * 0.45 < -2.45) azDes = Math.max(azDes, 5.0);

      const onPad = obs.gateIndex === 3 &&
        Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.12 &&
        p.y <= 0.088 &&
        Math.hypot(v.x, v.y, v.z) < 0.34;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const gTotal = Math.max(6.5, 9.81 + ayDes);
      const aBodyX = cy * axDes - sy * azDes;
      const aBodyZ = sy * axDes + cy * azDes;

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.12) ? 0.165 : 0.50;
      const pitchTarget = onPad ? 0 : clamp(Math.atan2(aBodyX, gTotal), -maxTilt, maxTilt);
      const rollTarget = onPad ? 0 : clamp(Math.atan2(-aBodyZ, gTotal), -maxTilt, maxTilt);

      pitchRef += (pitchTarget - pitchRef) * 0.22;
      rollRef += (rollTarget - rollRef) * 0.22;

      const pitch = onPad ? 0 : clamp(pitchTarget + pitchBias, -maxTilt, maxTilt);
      const roll = onPad ? 0 : clamp(rollTarget + rollBias, -maxTilt, maxTilt);

      const dirY = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrust = onPad ? 0.02 : clamp((9.81 + ayDes) / (kT * dirY), 0.12, 1.0);

      yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.0 * att.yaw - 1.2 * yawInt - 0.2 * rates.yaw, -2, 2);

      tNorm += (thrust - tNorm) * 0.22;
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirZ = -sy * bodyX + cy * bodyZ;
      const aThrust = kT * tNorm;
      vxEst += (aThrust * dirX - cd * vxEst + dxEst) * dt;
      vyEst += (aThrust * dirY - 9.81 - cd * vyEst + dyEst) * dt;
      vzEst += (aThrust * dirZ - cd * vzEst + dzEst) * dt;

      return { thrust, roll, pitch, yawRate };
    },
  };
}
