        gateIdx = obs.gateIndex;
        phase = 'clear_prev';
        settle = 0;
      }

      let tx, ty, tz, vxFf = 0, vyFf = 0, vzFf = 0;
      let kpX = 6.2, kdX = 4.8;
      let kpY = 7.5, kdY = 4.8;
      let kpZ = 7.2, kdZ = 5.0;
      let maxPosErrX = 0.45;

      // 1. After crossing a gate, keep lateral alignment until 11 cm past gate plane while already moderating X speed
