        const prev = gateIdx - 1;
        if (p.x < GATES_X[prev] + 0.11) {
          tx = GATES_X[prev] + 0.15;
          ty = GATES_Y[prev];
          tz = GATES_Z[prev];
          vxFf = 0.30;
          maxPosErrX = 0.15;
          kpX = 7.0; kdX = 5.2;
          kpY = 9.5; kdY = 5.5;
          kpZ = 11.0; kdZ = 6.0;
