            tx = g.x - 0.50;
            if (p.x > g.x - 0.18 && (errY > 0.17 || errZ > 0.085)) {
              ty = p.y;
              tz = p.z;
            } else {
              ty = g.y;
              tz = g.z;
            }
            maxPosErrX = 0.40;
            kpX = 8.5; kdX = 5.5;
