      if (p.x + vxEst * 0.45 < -2.45) axDes = Math.max(axDes, 5.0);
      if (p.z + vzEst * 0.45 > 2.45) azDes = Math.min(azDes, -5.0);
      if (p.z + vzEst * 0.45 < -2.45) azDes = Math.max(azDes, 5.0);

