      vyEst += (aThrust * dirY - 9.81 - cd * vyEst + dyEst) * dt;
      vzEst += (aThrust * dirZ - cd * vzEst + dzEst) * dt;

      return { thrust, roll, pitch, yawRate };
    },
  };
