      let axDes = clamp(kpX * ex + kdX * (vxFf - vxEst) - dxEst + cd * vxEst, -5.2, 5.2);
      let azDes = clamp(kpZ * ez + kdZ * (vzFf - vzEst) - dzEst + cd * vzEst, -6.2, 6.2);
      const ayDes = clamp(kpY * ey + kdY * (vyFf - vyEst) - dyEst + cd * vyEst, -2.2, 6.0);

